using MediatR;using Microsoft.AspNetCore.Mvc;using Namaa.Api.Contracts.Invoices;using Namaa.Api.Extensions;using Namaa.Application.Invoices.Commands.CreateInvoice;using Namaa.Application.Invoices.Commands.UpdateInvoice;using Namaa.Application.Invoices.Commands.AddInvoiceItem;using Namaa.Application.Invoices.Queries.GetInvoiceById;using Namaa.Application.Invoices.Queries.GetInvoices;namespace Namaa.Api.Controllers;[ApiController][Route("api/invoices")]public sealed class InvoicesController(ISender sender):ControllerBase{[HttpPost]public async Task<IActionResult>Create(CreateInvoiceRequest request,CancellationToken cancellationToken){var x=await sender.Send(new CreateInvoiceCommand(request.InvoiceNumber,request.IssueDate,request.DueDate,request.CreatedByUserId,request.ProjectId,request.CustomerId,request.Notes),cancellationToken);return x.IsFailure?x.ToActionResult(this):CreatedAtAction(nameof(GetById),new{id=x.Value.Id},x.Value);}[HttpGet]public async Task<IActionResult>GetAll(CancellationToken cancellationToken)=>(await sender.Send(new GetInvoicesQuery(),cancellationToken)).ToActionResult(this);[HttpGet("{id:long}")]public async Task<IActionResult>GetById(long id,CancellationToken cancellationToken)=>(await sender.Send(new GetInvoiceByIdQuery(id),cancellationToken)).ToActionResult(this);[HttpPut("{id:long}")]public async Task<IActionResult>Update(long id,UpdateInvoiceRequest request,CancellationToken cancellationToken)=>(await sender.Send(new UpdateInvoiceCommand(id,request.IssueDate,request.DueDate,request.Notes),cancellationToken)).ToActionResult(this);[HttpPost("{id:long}/items")]public async Task<IActionResult>AddItem(long id,AddInvoiceItemRequest request,CancellationToken cancellationToken)=>(await sender.Send(new AddInvoiceItemCommand(id,request.Description,request.Quantity,request.UnitPrice,request.DiscountAmount,request.TaxAmount,request.ServiceId),cancellationToken)).ToActionResult(this);}
